import {COACHES,coachQuote} from './environment.js?v=3.7.0';
import {GROUPS} from './config.js?v=3.7.0';
import {canChange} from './commands.js?v=3.7.0';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number(n).toLocaleString('fr-FR',{maximumFractionDigits:2})+' €';
export function environmentView(s,{busy=false,quote=null,domain=s.trainingPlan.domain}={}){
 const e=s.environment,c=e.contract,blocked=!canChange(s,{busy}),p=s.players.find(p=>p.id===s.hero);
 const button=(label,action,disabled=false)=>`<button class="secondary" data-action="${action}" ${disabled?'disabled':''}>${esc(label)}</button>`;
 const cost=x=>x.sessions?money(x.price/x.sessions):'—';
 let status='Choisissez une spécialité et consultez un devis avant tout paiement.';
 if(c)status=s.day<c.start?`Accompagnement à partir de J${c.start}.`:s.trainingPlan.domain!==c.domain?`Votre programme vise ${s.trainingPlan.domain}, mais la spécialité du coach est ${c.domain} : aucun bonus tant qu’ils ne correspondent pas.`:GROUPS[c.domain].every(k=>p.attrs[k]>=99)?'Domaine entièrement à 99 : aucun bonus, pas de prochain renouvellement.':p.injury?'Blessure : aucune séance accompagnée pendant l’indisponibilité.':s.activity==='repos'||p.fatigue>65?'Repos ou fatigue élevée : aucun bonus sans séance.':'Le coach accompagne les séances admissibles de votre programme. Aucun bonus direct en match.';
 if(c&&s.day<c.start&&s.trainingPlan.domain!==c.domain)status+=` Votre programme vise ${s.trainingPlan.domain}, mais la spécialité du coach est ${c.domain} : aucun bonus tant qu’ils ne correspondent pas.`;
 return `<section class="panel environment-panel"><p class="eyebrow">V3.7 · VOTRE PROGRESSION</p><h2>Mon environnement</h2><p>Achetez de meilleures conditions d’entraînement, pas des attributs. Votre progression habituelle reste gratuite.</p>
 <div class="stat-strip"><div><strong>${money(s.money)}</strong><span>Liquidités</span></div><div><strong>${money(s.life.finance.reserve)}</strong><span>Réserve protégée à l’achat</span></div><div><strong>${esc(s.trainingPlan.domain)}</strong><span>Programme actuel</span></div></div>
 <p class="data-note" role="status">${esc(status)}${e.notice?'<br>'+esc(e.notice):''}</p><div class="button-row">${button('Régler mon programme','coach-program',busy)}${button('Régler ma réserve','coach-finance',busy)}</div>
 ${c?`<article class="coach-active"><h3>${esc(COACHES[c.offerId].name)} · ${esc(c.domain)}</h3><p>J${c.start} à J${c.end} inclus · ${money(c.price)} payés · +${Math.round(c.rate*100)} % d’XP bruts ciblés.</p><div class="metrics"><article><span>Séances accompagnées</span><strong>${c.sessions}</strong></article><article><span>XP supplémentaires réels</span><strong>+${c.extraXP}</strong></article></div><p>Coût par séance : <b>${cost(c)}</b></p><p>Renouvellement ${e.renew?'activé':'désactivé'} · prochaine échéance J${c.end+1}.</p>${button(e.renew?'Résilier le renouvellement':'Activer le renouvellement','coach-renew',blocked)}<p class="muted">Résilier conserve la période payée jusqu’à son terme, sans remboursement. Changement de coach ou de spécialité à son terme.</p></article>`:
 `<label>Spécialité du coach<select id="coach-domain" ${blocked?'disabled':''}>${Object.keys(GROUPS).map(d=>`<option ${d===domain?'selected':''}>${esc(d)}</option>`).join('')}</select></label><div class="coach-grid">${Object.entries(COACHES).map(([id,o])=>{const q=coachQuote(s,id,domain);return `<article><h3>${esc(o.name)}</h3><p class="coach-price">${money(o.price)} <small>/ 30 jours</small></p><p>+${Math.round(o.rate*100)} % d’XP bruts en ${esc(domain)}, seulement lors des séances compatibles.</p>${button('Voir le devis','coach-quote:'+id,blocked)}${!q.ok?`<p class="muted">${esc(q.reason)}</p>`:''}</article>`;}).join('')}</div>`}
 ${quote?`<article class="data-note coach-quote" aria-label="Devis du coach"><h3>Votre devis · ${esc(quote.domain)}</h3><p>Débit immédiat : <b>${money(quote.price||0)}</b>. Disponible après achat : ${money(quote.balanceAfter??s.money)} ; réserve : ${money(quote.reserve)}.</p><p>Couverture : J${quote.start} à J${quote.end} inclus. Renouvellement désactivé par défaut.</p><p>Sans remboursement. Blessure, repos ou changement de programme ne prolongent pas la période. À 99 dans tout le domaine, le bonus cesse et le renouvellement est refusé.</p><p>Les renouvellements utilisent les fonds disponibles avant les revenus du jour et préservent votre réserve.</p>${quote.ok?'':`<p role="alert">${esc(quote.reason)}</p>`}<div class="button-row">${button('Confirmer et payer','coach-confirm',blocked||!quote.ok)}${button('Fermer le devis','coach-dismiss',busy)}</div></article>`:''}
 <details><summary>Bilan de mon environnement · ${e.history.length} période(s) clôturée(s)</summary><p>Depuis le début : ${money(e.totals.paid)} payés · ${e.totals.sessions} séances · ${e.totals.extraXP} XP supplémentaires.</p><p class="muted">Les XP mesurent la différence réellement accordée par séance, après arrondi. Ils ne sont pas une promesse de points d’attribut. Les 24 dernières périodes sont détaillées ; les totaux restent conservés.</p>${[...e.history].reverse().map(h=>`<article><h4>${esc(COACHES[h.offerId].name)} · ${esc(h.domain)} · J${h.start}–J${h.end}</h4><p>${money(h.price)} · ${h.sessions} séances · +${h.extraXP} XP · coût/séance ${cost(h)}<br>${esc(h.reason)}</p></article>`).join('')||'<p>Aucune période clôturée.</p>'}</details></section>`;
}
